mapper.select:
select workbook_id, name, doc_type, content, user_id,
       create_by, create_time, update_by, update_time
from ai_workbook
where workbook_id = #{workbookId}
  and user_id = #{userId}

mapper.delete:
delete from ai_workbook
where workbook_id = #{workbookId}
  and user_id = #{userId}

mapper.select:
select count(*)
from ai_workbook
where user_id = #{userId}
  and name = #{name}

  and workbook_id != #{excludeId}

mapper.update:
update ai_workbook
set name = #{name},
    update_by = #{updateBy},
    update_time = now()
where workbook_id = #{workbookId}
  and user_id = #{userId}
